<?php use Aibid\Http\View as V; ?>
<div class="page-heading"><div><span class="eyebrow">DIRECTORIO COMERCIAL</span><h1>Clientes</h1><p>Datos de contacto y relaciones comerciales.</p></div><?php if ($actor->canWrite()): ?><a class="btn btn-primary" href="/admin/customers/new">＋ Nuevo cliente</a><?php endif; ?></div>
<section class="panel"><form class="filter-bar" method="get"><div class="search-field"><label class="visually-hidden" for="q">Buscar clientes</label><input id="q" name="q" class="form-control" placeholder="Buscar por cliente o correo…" value="<?= V::escape($filters['q']) ?>"></div><label class="visually-hidden" for="state">Estado</label><select class="form-select filter-select" id="state" name="state"><option value="">Todos los estados</option><option value="active" <?= $filters['state']==='active'?'selected':'' ?>>Activos</option><option value="archived" <?= $filters['state']==='archived'?'selected':'' ?>>Archivados</option></select><button class="btn btn-outline-secondary">Filtrar</button></form>
<?php if (!$listing['rows']): ?><div class="empty-state"><h3>No hay clientes para mostrar</h3><p>Registra un cliente nuevo o ajusta los filtros de búsqueda.</p></div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Cliente</th><th>Contacto</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($listing['rows'] as $customer): ?><tr><td><strong><?= V::escape($customer['display_name']) ?></strong><small class="cell-sub"><?= V::escape($customer['legal_name']) ?></small></td><td><?= V::escape($customer['contact_name']) ?><small class="cell-sub"><?= V::escape($customer['email']) ?></small></td><td><span class="tag <?= $customer['state']==='active'?'tag-green':'' ?>"><?= $customer['state']==='active'?'Activo':'Archivado' ?></span></td><td><a class="text-link" href="/admin/customers/<?= V::escape($customer['id_text']) ?>">Abrir →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php require __DIR__.'/pagination.php'; ?></section>
